namespace cw::binary::cwscenario {using B=::cw::binary::base::CWBinaryBase;using S=::cw::lib::String;using I=::cw::lib::Integer;namespace{S low(S s){for(auto&c:s)c=(char)std::tolower((unsigned char)c);return s;}S path8(const std::filesystem::path&p){return ::cw::lib::encoding::path_to_utf8(p);}S name(const S&p){return path8(std::filesystem::u8path(p).filename());}S ext(const S&p){const auto f=name(p);auto e=path8(std::filesystem::u8path(f).extension());if(e.empty()&&f.size()>1&&f.front()=='.'&&f.find('.',1)==S::npos)e=f;if(!e.empty())e.erase(0,1);return low(e);}bool starts(const S&s,const S&p){return low(s).rfind(low(p),0)==0;}::cw::lib::Value value(const std::shared_ptr<B>&p){if(!p)return{};return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(p));}std::shared_ptr<B>object(const std::optional<::cw::lib::Value>&v){if(v)if(auto*o=std::get_if<::cw::lib::ObjectPtr>(&v->storage()))return std::dynamic_pointer_cast<B>(*o);return{};}S join(const S&a,const S&b){return ::cw::binary::util::join_paths({::cw::lib::Value(a),::cw::lib::Value(b)});}
struct Entry{std::filesystem::path path;bool file{};bool directory{};};
std::vector<Entry> list(const std::filesystem::path&dir){std::vector<Entry>result;if(::cardwirth::platform::is_mounted_user_path(dir)){const auto entries=::cardwirth::platform::list_mounted_user_path(dir);if(!entries)throw std::runtime_error("failed to list mounted classic scenario: "+path8(dir));for(const auto&e:*entries)result.push_back({e.path,e.stat.is_file(),e.stat.is_directory()});return result;}for(const auto&e:std::filesystem::directory_iterator(dir))result.push_back({e.path(),e.is_regular_file(),e.is_directory()});return result;}
void mkdirs(const std::filesystem::path&path){if(::cardwirth::platform::is_mounted_user_path(path)){if(!::cardwirth::platform::make_mounted_user_directory(path,true))throw std::runtime_error("failed to create mounted classic scenario directory: "+path8(path));return;}std::filesystem::create_directories(path);}
void copy_path(const std::filesystem::path&source,const std::filesystem::path&destination){const bool sm=::cardwirth::platform::is_mounted_user_path(source),dm=::cardwirth::platform::is_mounted_user_path(destination);if(sm&&dm){if(!::cardwirth::platform::copy_mounted_user_path(source,destination,true))throw std::runtime_error("failed to copy mounted classic scenario path: "+path8(source));return;}if(sm||dm)throw std::runtime_error("classic scenario conversion cannot cross encrypted storage boundary");if(std::filesystem::is_directory(source))std::filesystem::copy(source,destination,std::filesystem::copy_options::recursive|std::filesystem::copy_options::overwrite_existing);else std::filesystem::copy_file(source,destination,std::filesystem::copy_options::overwrite_existing);}
}
void CWScenario::initialize(S path,S dst,S skin,S material,bool images){m_name=name(path);m_path=std::move(path);m_dir=::cw::binary::util::check_duplicate(join(dst,m_name));m_skintype=std::move(skin);m_materialdir=std::move(material);m_image_export=images;m_message.clear();m_curnum=0;m_maxnum=1;m_datalist.clear();m_errorlog.clear();m_cwfiles.clear();m_materials.clear();m_otherfiles.clear();m_otherdirs.clear();m_summarypath.reset();m_versionhint.reset();m_hasmodeini=false;m_imgdir.clear();if(m_path.empty())return;static const std::set<S>materials{"bmp","jpg","jpeg","wav","wave","mid","midi","jpdc","jpy1","jptx"};for(const auto&e:list(std::filesystem::u8path(m_path))){S n=path8(e.path.filename()),p=join(m_path,n),ln=low(n),x=ext(n);if(e.file){if(ln=="summary.wsm"&&!m_summarypath){m_summarypath=p;m_cwfiles.push_back(p);}else if(x=="wid")m_cwfiles.push_back(p);else if(materials.contains(x))m_materials.push_back(p);else if(ln=="mode.ini")read_modeini(p);else m_otherfiles.push_back(p);}else if(e.directory)m_otherdirs.push_back(p);}if(m_summarypath&&::cw::g_cwpy&&::cw::g_cwpy->m_sct)m_versionhint=::cw::g_cwpy->m_sct->merge_versionhints(m_versionhint,::cw::g_cwpy->m_sct->get_versionhint(*m_summarypath,std::nullopt));}
void CWScenario::read_modeini(S path){if(::cw::g_cwpy&&::cw::g_cwpy->m_sct)if(auto hint=::cw::g_cwpy->m_sct->read_modeini(path)){m_versionhint=hint;m_hasmodeini=true;}}void CWScenario::write_errorlog(S s){m_errorlog+=std::move(s)+"\n";}bool CWScenario::is_yadodata(){return false;}bool CWScenario::is_convertible(){if(!m_summarypath)return false;auto [v,b]=load_file(*m_summarypath);auto s=std::dynamic_pointer_cast<::cw::binary::summary::Summary>(object(v));return s&&s->m_version<=4;}
std::tuple<std::optional<::cw::lib::Value>,std::optional<::cw::lib::Bytes>>CWScenario::load_file(S path,bool nameonly,bool decode){try{auto f=std::make_shared<::cw::binary::cwfile::CWFile>(path,"rb",decode);std::shared_ptr<B>d;auto filename=name(path),x=ext(path);if(x=="wsm"){auto v=std::make_shared<::cw::binary::summary::Summary>();v->initialize({},f,false,nameonly,m_materialdir,m_image_export,false);v->m_skintype=m_skintype;d=v;}else{I t=f->byte();f->seek(0);f->m_filedata.clear();if(t==0){auto v=std::make_shared<::cw::binary::area::Area>();v->initialize({},f,false,nameonly,m_materialdir,m_image_export);d=v;}else if(t==1||(t==2&&starts(filename,"battle"))){auto v=std::make_shared<::cw::binary::battle::Battle>();v->initialize({},f,false,nameonly,m_materialdir,m_image_export);d=v;}else if(t==2||(t==4&&starts(filename,"mate"))){auto v=std::make_shared<::cw::binary::cast::CastCard>();v->initialize({},f,false,nameonly,m_materialdir,m_image_export);d=v;}else if(t==3||(t==5&&starts(filename,"item"))){auto v=std::make_shared<::cw::binary::item::ItemCard>();v->initialize(std::nullopt,f,false,nameonly,m_materialdir,m_image_export);d=v;}else if(t==4&&starts(filename,"package")){auto v=std::make_shared<::cw::binary::package::Package>();v->initialize({},f,false,nameonly,m_materialdir,m_image_export);d=v;}else if(t==4||(t==6&&starts(filename,"info"))){auto v=std::make_shared<::cw::binary::info::InfoCard>();v->initialize({},f,false,nameonly,m_materialdir,m_image_export);d=v;}else if(t==5||t==7){auto v=std::make_shared<::cw::binary::skill::SkillCard>();v->initialize(std::nullopt,f,false,nameonly,m_materialdir,m_image_export);d=v;}else if(t==6||t==8){auto v=std::make_shared<::cw::binary::beast::BeastCard>();v->initialize(std::nullopt,f,false,nameonly,m_materialdir,m_image_export,false);d=v;}else throw std::invalid_argument(path);}if(!nameonly)(void)f->read();::cw::lib::Bytes filedata;for(const auto&chunk:f->m_filedata)filedata.insert(filedata.end(),chunk.begin(),chunk.end());f->close();return{value(d),std::move(filedata)};}catch(...){::cw::util::print_ex(std::nullopt);return{std::nullopt,std::nullopt};}}
void CWScenario::load(){m_datalist.clear();for(auto&p:m_cwfiles){auto[v,b]=load_file(p);auto d=object(v);if(d)m_datalist.push_back(d);else write_errorlog(name(p)+" は読込できませんでした。\n");}m_maxnum=(I)(m_datalist.size()+m_materials.size()+m_otherfiles.size()+m_otherdirs.size());}
// ネイティブの変換は、変換・コピー前に出力ルートを作り、途中失敗
// も含め共通の全保存経路で存在させる。 コピーは shutil.copy2
// ではなくネイティブ・マウント済みの保存機能を使い、ここで
// は元の付加情報の保持を明示要求しない。 この方針だけから
// 、ファイル・ディレクトリの更新日時の実測差を推定しない。
S CWScenario::convert(const std::function<void(::cw::lib::Integer,const S&)>& progress){if(m_datalist.empty())load();m_curnum=0;if(progress)progress(m_curnum,m_message);mkdirs(std::filesystem::u8path(m_dir));for(auto&d:m_datalist){m_message=name(d->m_fpath)+" を変換中...";++m_curnum;if(progress)progress(m_curnum,m_message);try{d->create_xml(m_dir);}catch(...){::cw::util::print_ex(std::nullopt);write_errorlog(name(d->m_fpath)+" は変換できませんでした。\n");}}auto mat=join(m_dir,"Material");mkdirs(std::filesystem::u8path(mat));for(auto&p:m_materials){m_message=name(p)+" をコピー中...";++m_curnum;if(progress)progress(m_curnum,m_message);auto dst=::cw::binary::util::check_duplicate(join(mat,name(p)));copy_path(std::filesystem::u8path(p),std::filesystem::u8path(dst));}for(auto&p:m_otherfiles){m_message=name(p)+" をコピー中...";++m_curnum;if(progress)progress(m_curnum,m_message);auto dst=::cw::binary::util::check_duplicate(join(m_dir,name(p)));copy_path(std::filesystem::u8path(p),std::filesystem::u8path(dst));}for(auto&p:m_otherdirs){m_message=name(p)+" をコピー中...";++m_curnum;if(progress)progress(m_curnum,m_message);auto dst=::cw::binary::util::check_duplicate(join(m_dir,name(p)));copy_path(std::filesystem::u8path(p),std::filesystem::u8path(dst));}m_curnum=m_maxnum;if(progress)progress(m_curnum,m_message);return m_dir;}void main(){}
}
